const fs = require('fs');
const path = require('path');
const os = require('os');
const process = require('process');

const body = $input.first().json?.body || $input.first().json || {};
const projectId = String(body.project_id || '').trim();
if (!projectId) throw new Error('读取脚本上下文：缺少 project_id');

function projectRoot() {
  const env = require('process').env || {};
  return env.TIKTOK_WORKFLOW_ROOT || env.PROJECT_ROOT || process.cwd();
}

const root = projectRoot();
const dataRoot = require('process').env.WORKFLOW_DATA_ROOT || (require('process').platform === 'win32' ? require('path').join(require('process').env.APPDATA || require('path').join(require('process').env.USERPROFILE || require('process').env.HOME || require('os').homedir(), 'AppData', 'Roaming'), 'AI Video', 'workflow-data') : require('path').join(require('os').homedir(), 'Library', 'Application Support', 'AI Video', 'workflow-data')) || require('process').env.AI_VIDEO_RUNTIME_ROOT || root;
const scriptContextDir = path.join(dataRoot, '.n8n-local-cache', 'script-context');
const fileName = 'script_context_' + projectId.replace(/[^a-zA-Z0-9_-]+/g, '_') + '.json';
const filePath = path.join(scriptContextDir, fileName);

if (!fs.existsSync(filePath)) {
  throw new Error('读取脚本上下文：找不到脚本上下文文件 ' + filePath + '。请先运行 WF02A 生成脚本。');
}

const scriptContext = JSON.parse(fs.readFileSync(filePath, 'utf8'));

// Apply user overrides to shots if present
const overridesFileName = 'script_user_overrides_' + projectId.replace(/[^a-zA-Z0-9_-]+/g, '_') + '.json';
const overridesPath = path.join(scriptContextDir, overridesFileName);
let userOverrides = {};
if (fs.existsSync(overridesPath)) {
  try { userOverrides = JSON.parse(fs.readFileSync(overridesPath, 'utf8')); } catch (e) {}
}

let shots = Array.isArray(scriptContext.shots) ? [...scriptContext.shots] : [];
if (Array.isArray(userOverrides.shots) && userOverrides.shots.length > 0) {
  const overrideMap = {};
  for (const ov of userOverrides.shots) {
    if (ov.shot_id) overrideMap[ov.shot_id] = ov;
  }
  shots = shots.map(shot => {
    const ov = overrideMap[shot.shot_id];
    return ov ? { ...shot, ...ov } : shot;
  });
}

// Update project-state: stage = storyboard_generating
const projectStateDir = path.join(dataRoot, '.n8n-local-cache', 'project-state');
const projectStatePath = path.join(projectStateDir, 'project_' + projectId.replace(/[^a-zA-Z0-9_-]+/g, '_') + '.json');
let projectState = {};
try { if (fs.existsSync(projectStatePath)) projectState = JSON.parse(fs.readFileSync(projectStatePath, 'utf8')); } catch (e) {}
projectState.stage = 'storyboard_generating';
projectState.updated_at = new Date().toISOString();
fs.writeFileSync(projectStatePath, JSON.stringify(projectState, null, 2));

return [{
  json: {
    ...scriptContext,
    shots,
    user_overrides_applied: Object.keys(userOverrides).length > 0,
    review_round: Number(body.review_round || scriptContext.review_round || 1),
  }
}];

const fs = require('fs');
const path = require('path');
const os = require('os');

const input = $input.first();
const baseJson = input?.json || {};
const baseBinary = input?.binary || {};

function projectRoot() {
  const env = require('process').env || {};
  const candidates = [env.TIKTOK_WORKFLOW_ROOT, env.PROJECT_ROOT, require('process').cwd()].filter(Boolean);
  for (const root of candidates) {
    try { if (fs.existsSync(path.join(root, 'prompts', 'prompt_center.json'))) return root; } catch (_e) {}
  }
  throw new Error('Prompt Library: prompts/prompt_center.json not found. Checked: ' + candidates.join(', '));
}

function readJsonIfExists(filePath) {
  try {
    if (fs.existsSync(filePath)) {
      return JSON.parse(fs.readFileSync(filePath, 'utf8'));
    }
  } catch (error) {}
  return {};
}

const root = projectRoot();
const prompts = readJsonIfExists(path.join(root, 'prompts', 'prompt_center.json'));
if (!Object.keys(prompts).length) {
  throw new Error('Prompt Library: 无法读取 prompts/prompt_center.json，请检查 TIKTOK_WORKFLOW_ROOT/PROJECT_ROOT 或项目目录位置');
}

const legacy = readJsonIfExists(path.join(root, 'tiktok-workflow-prompts.json'));
const fallbackStoryboardGrid = {
  cols: 3,
  rows: 2,
  panel_aspect: '9:16',
  normalize_canvas_aspect: '27:32',
  supported_panel_counts: [6],
  supported_layouts: { '6': '3x2 => 27:32' },
  crop_inset_ratio: 0.01,
  output_mime_type: 'image/jpeg',
  output_extension: 'jpg',
  jpeg_quality: 90,
  panel_output_width: 1080,
  panel_output_height: 1920,
  panel_order: 'row_major_left_to_right',
};
const fallbackCreativeTaskTypeMapping = {
  _meta: { version: 'runtime-fallback', description: '最小创作任务映射，完整配置优先来自 prompt_center.json' },
  '种草': { video_type: 'local_voiceover', recommended_grid: '6_grid' },
  '口播': { video_type: 'local_voiceover', recommended_grid: '6_grid' },
  '开箱': { video_type: 'pure_display_or_light_voiceover', recommended_grid: '6_grid' },
  '产品展示': { video_type: 'mixed', recommended_grid: '6_grid' },
  '痛点前置': { video_type: 'local_voiceover', recommended_grid: '6_grid' },
  '自由创作': { video_type: 'mixed', recommended_grid: '6_grid' },
  '服装产品展示': { video_type: 'apparel_product_display', recommended_grid: '6_grid' },
  'OOTD穿搭展示': { video_type: 'style_showcase_ootd', recommended_grid: '6_grid' },
  '穿搭展示': { video_type: 'style_showcase_ootd', recommended_grid: '6_grid' },
  '风格展示': { video_type: 'style_showcase_ootd', recommended_grid: '6_grid' },
  '上身试穿展示': { video_type: 'style_showcase_ootd', recommended_grid: '6_grid' },
  '故事剧情带货': { video_type: 'story_drama', recommended_grid: '6_grid' },
  '真实故事剧情': { video_type: 'story_drama', recommended_grid: '6_grid' },
  '爆点故事剧情': { video_type: 'story_drama', recommended_grid: '6_grid' },
};

const runtimePrompts = {
  ...prompts,
  storyboard_grid: prompts.storyboard_grid || legacy.storyboard_grid || fallbackStoryboardGrid,
  creative_task_type_mapping: prompts.creative_task_type_mapping || legacy.creative_task_type_mapping || fallbackCreativeTaskTypeMapping,
};

return [{ json: { ...baseJson, ...runtimePrompts }, binary: baseBinary }];

const fs = require('fs');
const item = $input.first();
const json = item.json || {};
const binary = item.binary || {};

function pathFromMeta(entry) {
  if (!entry) return '';
  if (typeof entry === 'string') return entry;
  return entry.path || entry.local_path || entry.filePath || '';
}
function compactUnique(paths) {
  const seen = new Set();
  const out = [];
  for (const value of paths) {
    const p = String(value || '').trim();
    if (!p || seen.has(p)) continue;
    seen.add(p);
    out.push(p);
  }
  return out;
}
const imagePaths = Array.isArray(json.product_image_local_paths) ? json.product_image_local_paths : [];
const metaImages = Array.isArray(json.product_images_meta) ? json.product_images_meta : [];
const orderedPaths = compactUnique([
  json.image_1_path,
  json.image_2_path,
  json.image_3_path,
  json.image_4_path,
  json.image_5_path,
  ...imagePaths,
  ...metaImages.map(pathFromMeta),
]);
let sharp = null;
try { sharp = require('sharp'); } catch (_) { sharp = null; }
const PRODUCT_IDENTITY_SCORE_THRESHOLD = 0.58;

async function scoreProductIdentityReference(filePath) {
  if (!sharp || !filePath || !fs.existsSync(filePath)) return 0;
  try {
    const meta = await sharp(filePath).metadata();
    const width = Number(meta.width || 0);
    const height = Number(meta.height || 0);
    if (!width || !height) return 0;
    const { data, info } = await sharp(filePath)
      .resize(96, 96, { fit: 'inside' })
      .ensureAlpha()
      .raw()
      .toBuffer({ resolveWithObject: true });
    const total = Math.max(1, info.width * info.height);
    let nearWhite = 0;
    let veryWhite = 0;
    let transparent = 0;
    let colored = 0;
    for (let i = 0; i < data.length; i += 4) {
      const r = data[i];
      const g = data[i + 1];
      const b = data[i + 2];
      const a = data[i + 3];
      if (a < 16) { transparent++; continue; }
      const max = Math.max(r, g, b);
      const min = Math.min(r, g, b);
      if (r > 238 && g > 238 && b > 238) veryWhite++;
      if (r > 220 && g > 220 && b > 220 && max - min < 22) nearWhite++;
      if (max - min > 32 || max < 210) colored++;
    }
    const cleanBackgroundScore = Math.min(1, (nearWhite + transparent) / total);
    const pureBackgroundBonus = Math.min(1, veryWhite / total) * 0.2;
    const visibleProductScore = Math.min(1, colored / total) * 0.6;
    return Number((cleanBackgroundScore + pureBackgroundBonus + visibleProductScore).toFixed(4));
  } catch (_) {
    return 0;
  }
}

const scoredPaths = [];
for (let i = 0; i < orderedPaths.length; i++) {
  const p = orderedPaths[i];
  scoredPaths.push({ path: p, originalIndex: i, identityScore: await scoreProductIdentityReference(p) });
}
const identityReferences = scoredPaths
  .filter((entry) => entry.identityScore >= PRODUCT_IDENTITY_SCORE_THRESHOLD)
  .sort((a, b) => b.identityScore - a.identityScore || a.originalIndex - b.originalIndex);
const supportingReferences = scoredPaths
  .filter((entry) => entry.identityScore < PRODUCT_IDENTITY_SCORE_THRESHOLD)
  .sort((a, b) => a.originalIndex - b.originalIndex);
const orderedReferencePaths = compactUnique([
  ...identityReferences.map((entry) => entry.path),
  ...supportingReferences.map((entry) => entry.path),
]);
const requestedImageCount = Math.max(Number(json.product_image_count ?? json.image_count ?? orderedReferencePaths.length ?? 0), orderedReferencePaths.length, metaImages.length);
const selectedImagePaths = orderedReferencePaths.slice(0, requestedImageCount);
const imageCount = requestedImageCount;

async function readImageBase64(index, pathValue) {
  if (json['image_' + (index + 1) + '_base64']) return String(json['image_' + (index + 1) + '_base64']);
  if (pathValue && fs.existsSync(pathValue)) return fs.readFileSync(pathValue).toString('base64');
  try {
    const img = await this.helpers.getBinaryDataBuffer(0, 'product_images_' + index);
    return img.toString('base64');
  } catch (e) {
    return '';
  }
}
const imageEntries = [];
for (let i = 0; i < imageCount; i++) {
  const n = i + 1;
  const filePath = selectedImagePaths[i] || orderedPaths[i] || json['image_' + n + '_path'] || '';
  const data = await readImageBase64.call(this, i, filePath);
  const mime = binary['product_images_' + i]?.mimeType || json['image_' + n + '_mime'] || metaImages[i]?.mimeType || 'image/jpeg';
  if (data && String(data).length > 100) imageEntries.push({ index: n, path: filePath, mime, data });
}

const shots = json.shots || [];
const expectedTotalPanels = shots.length;
const expectedLayoutLabel = '6-panel (3x2, target 27:32)';
if (expectedTotalPanels !== 6) throw new Error('分镜提示词生成前校验失败：当前工作流已强制六宫格，shots 数量必须为 6，实际为 ' + expectedTotalPanels);

let fullScriptJson = {
  script_overview: {
    selected_concept_name_original: json.selected_concept_name_original || '',
    script_concept_label: json.script_concept_label || '',
    script_goal: json.script_goal || '',
    visual_style: json.visual_style || '',
    identified_product_type: json.identified_product_type || '',
    product_presentation_logic: json.product_presentation_logic || '',
    core_visual_focus: json.core_visual_focus || '',
    total_shots: json.total_shots || 6,
    hook_strategy: json.hook_strategy || '',
    target_user: json.target_user || '',
    usage_scene: json.usage_scene || '',
    visual_expression: json.visual_expression || '',
    model_profile: json.model_profile || '',
    core_selling_angle: json.core_selling_angle || '',
  },
  shots,
};
if (json.full_script_json) {
  try { fullScriptJson = JSON.parse(json.full_script_json); } catch (e) {}
}
function tpl(str, vars) {
  let out = str;
  for (const [k, v] of Object.entries(vars)) out = out.split('{{' + k + '}}').join(v == null ? '' : String(v));
  return out;
}
function productImageMetaJson(input) {
  const meta = Array.isArray(input.product_images_meta) ? input.product_images_meta : [];
  const selected = selectedImagePaths.length ? selectedImagePaths : orderedPaths.slice(0, imageCount);
  return JSON.stringify(selected.map((filePath, index) => {
    const img = meta.find((entry) => pathFromMeta(entry) === filePath) || meta[index] || {};
    const scored = scoredPaths.find((entry) => entry.path === filePath) || {};
    const isIdentity = Number(scored.identityScore || 0) >= PRODUCT_IDENTITY_SCORE_THRESHOLD;
    return {
      index: index + 1,
      fileName: img.fileName || img.original_filename || '',
      path: filePath,
      consistency_role: isIdentity ? 'product_identity_reference' : (img.consistency_role || img.role || (index === 0 ? 'primary_product_reference' : 'supporting_detail_reference')),
      identityScore: Number(scored.identityScore || 0),
      role_note: img.role_note || (isIdentity ? 'auto-ranked as product identity / clean-background reference' : 'supporting usage/detail reference'),
    };
  }), null, 2);
}

const prompts = $('Prompt Library').first().json;
const sb = prompts.storyboard;
const userText = tpl(sb.user_template, {
  project_id: json.project_id || '',
  product_name: json.product_name || '',
  target_market: json.target_market || '',
  target_language: json.target_language || '',
  creative_task_type: json.creative_task_type || '',
  selected_concept_name_original: json.selected_concept_name_original || '',
  script_concept_label: json.script_concept_label || '',
  script_goal: json.script_goal || '',
  visual_style: json.visual_style || '',
  identified_product_type: json.identified_product_type || '',
  product_presentation_logic: json.product_presentation_logic || '',
  core_visual_focus: json.core_visual_focus || '',
  hook_strategy: json.hook_strategy || '',
  expected_total_panels: String(expectedTotalPanels),
  expected_layout_label: expectedLayoutLabel,
  full_script_json: JSON.stringify(fullScriptJson, null, 2),
  shots_json: JSON.stringify(shots, null, 2),
  product_images_json: productImageMetaJson(json),
  product_consistency_rule: json.product_consistency_rule || '',
});
const hardConstraintBlock = [
  '',
  '【Form 业务硬约束】',
  '- target_market 必须严格使用：' + (json.target_market || ''),
  '- target_language（视频字幕/口播/台词的目标语言，不是 JSON 字段的输出语言）：' + (json.target_language || ''),
  '- 【输出语言强制要求】所有 JSON 审核字段（concept_name、core_selling_angle、target_user、pain_point、usage_scene、visual_expression 等）必须使用中文，禁止用 target_language 作为 JSON 字段的输出语言。',
  '- creative_task_type 必须严格使用：' + (json.creative_task_type || ''),
  '- creative_task_type_rules：' + (json.creative_task_type_rules_json || '{}'),
  '- recommended_grid：' + (json.recommended_grid || '6_grid'),
  '- selected_concept 是人工选择后的硬约束，不允许推翻。',
  '- product_image_count：' + imageCount,
  '- product_images_json：' + productImageMetaJson(json),
  '- product_reference_strategy：' + (identityReferences.length ? 'product_identity_references_first' : 'first_uploaded_reference_fallback'),
  '- 本次优先发送给模型的产品图顺序：' + (selectedImagePaths.length ? selectedImagePaths.map((p, i) => (i + 1) + ':' + p).join(' | ') : '(no image path)'),
  '- 用户关键操作锁：若产品名称、卖点、已选创意方向或保存变量里出现明确动作/结果形态/使用对象/接触位置，必须在脚本、分镜和视频提示词中原样承接；不得用相近动作替代。',
  '- 产品一致性硬规则：如上传图中存在白底图/纯产品图/主产品图，它是产品主体身份的最高优先级参考；NanoBanana 总提示词必须以其产品形状、颜色、尺寸、材质、结构、可见部件和 SKU 身份为准。其他场景图/细节图只能补充使用场景、手部动作、环境或细节，不得覆盖主产品身份。',
  json.target_user ? '- target_user（目标用户，硬约束）：' + json.target_user : '',
  json.usage_scene ? '- usage_scene（使用场景，硬约束）：' + json.usage_scene : '',
  json.visual_expression ? '- content_style（内容风格，硬约束）：' + json.visual_expression : '',
  json.hook_strategy ? '- hook_strategy（视觉Hook，硬约束）：' + json.hook_strategy : '',
  json.model_profile ? '- model_profile（人物/模特设定，硬约束）：' + json.model_profile : '',
].filter(Boolean).join('\\n');
const parts = [{ text: userText + hardConstraintBlock }];
for (const image of imageEntries) parts.push({ inline_data: { mime_type: image.mime, data: image.data } });
const imageFields = {};
for (const image of imageEntries) {
  imageFields['image_' + image.index + '_path'] = image.path;
  imageFields['image_' + image.index + '_mime'] = image.mime;
  imageFields['image_' + image.index + '_base64'] = image.data;
}
return [{
  json: {
    ...json,
    ...imageFields,
    image_count: imageCount,
    product_image_count: imageCount,
    product_reference_image_paths: selectedImagePaths,
    product_identity_reference_paths: (identityReferences.length ? identityReferences : scoredPaths.slice().sort((a, b) => b.identityScore - a.identityScore || a.originalIndex - b.originalIndex).slice(0, 1)).map((entry) => entry.path),
    product_reference_strategy: identityReferences.length ? 'product_identity_references_first' : 'first_uploaded_reference_fallback',
    request_body: {
      system_instruction: { parts: [{ text: sb.system_instruction }] },
      contents: [{ role: 'user', parts }],
      generationConfig: sb.generation_config,
    },
  },
}];

const row = $input.first().json || {};

function pickImagePaths(input) {
  if (Array.isArray(input.product_image_local_paths) && input.product_image_local_paths.length > 0) {
    return input.product_image_local_paths.filter(Boolean);
  }
  if (Array.isArray(input.默认测试图片路径) && input.默认测试图片路径.length > 0) {
    return input.默认测试图片路径.filter(Boolean);
  }
  if (Array.isArray(input.product_images_meta)) {
    return input.product_images_meta
      .map((entry) => (typeof entry === 'string' ? entry : entry?.path || ''))
      .filter(Boolean);
  }
  return [];
}

const imagePaths = pickImagePaths(row);
const metaImages = Array.isArray(row.product_images_meta) ? row.product_images_meta : [];
const explicitImageCount = Number(row.product_image_count ?? row.image_count ?? 0);
const imageCount = Math.max(explicitImageCount, imagePaths.length, metaImages.length);

return [
  {
    json: {
      ...row,
      project_id: row.project_id || '',
      product_name: row.product_name || '',
      target_market: row.target_market || '',
      target_language: row.target_language || '',
      creative_task_type: row.creative_task_type || '',
      reference_case_url: row.reference_case_url || '',
      product_image_local_paths: imagePaths,
      product_image_count: imageCount,
      image_count: imageCount,
      image_1_path: row.image_1_path || imagePaths[0] || '',
      image_2_path: row.image_2_path || imagePaths[1] || '',
      使用默认测试图片: !!row.使用默认测试图片,
    },
  },
];

const fs = require('fs');
const path = require('path');

const row = $input.first().json || {};
const PRODUCT_IDENTITY_SCORE_THRESHOLD = 0.95;

function pathFromMeta(entry) {
  if (!entry) return '';
  if (typeof entry === 'string') return entry;
  return entry.path || entry.local_path || entry.filePath || '';
}

function compactUnique(paths) {
  const seen = new Set();
  const out = [];
  for (const value of paths) {
    const p = String(value || '').trim();
    if (!p || seen.has(p)) continue;
    seen.add(p);
    out.push(p);
  }
  return out;
}

const imagePaths = Array.isArray(row.product_image_local_paths)
  ? row.product_image_local_paths.filter(Boolean)
  : [];
const metaImages = Array.isArray(row.product_images_meta) ? row.product_images_meta : [];
const orderedPaths = compactUnique([
  row.image_1_path,
  row.image_2_path,
  row.image_3_path,
  row.image_4_path,
  ...imagePaths,
  ...metaImages.map(pathFromMeta),
]);
const explicitImageCount = Number(row.product_image_count ?? row.image_count ?? 0);
const imageCount = Math.max(explicitImageCount, imagePaths.length, metaImages.length, orderedPaths.length);

let sharp = null;
try {
  sharp = require('sharp');
} catch (_) {
  sharp = null;
}

function readImageAsInlineData(filePath) {
  if (!filePath || !fs.existsSync(filePath)) {
    return null;
  }
  const ext = path.extname(filePath).toLowerCase();
  const mimeType =
    ext === '.png' ? 'image/png' : ext === '.jpg' || ext === '.jpeg' ? 'image/jpeg' : 'application/octet-stream';
  return { path: filePath, mimeType, data: fs.readFileSync(filePath).toString('base64') };
}

async function scoreProductIdentityReference(filePath) {
  if (!sharp || !filePath || !fs.existsSync(filePath)) return 0;
  try {
    const meta = await sharp(filePath).metadata();
    const width = Number(meta.width || 0);
    const height = Number(meta.height || 0);
    if (!width || !height) return 0;
    const { data, info } = await sharp(filePath)
      .resize(96, 96, { fit: 'inside' })
      .ensureAlpha()
      .raw()
      .toBuffer({ resolveWithObject: true });
    const total = Math.max(1, info.width * info.height);
    let nearWhite = 0;
    let veryWhite = 0;
    let dark = 0;
    let colored = 0;
    for (let i = 0; i < data.length; i += 4) {
      const r = data[i];
      const g = data[i + 1];
      const b = data[i + 2];
      const a = data[i + 3];
      if (a < 8) {
        nearWhite++;
        veryWhite++;
        continue;
      }
      const max = Math.max(r, g, b);
      const min = Math.min(r, g, b);
      const brightness = (r + g + b) / 3;
      if (r > 238 && g > 238 && b > 238) veryWhite++;
      if (r > 220 && g > 220 && b > 220 && max - min < 30) nearWhite++;
      if (brightness < 80) dark++;
      if (max - min > 45 && brightness > 80 && brightness < 245) colored++;
    }
    const nearWhiteRatio = nearWhite / total;
    const veryWhiteRatio = veryWhite / total;
    const darkRatio = dark / total;
    const coloredRatio = colored / total;
    const squareLikeBonus = Math.abs(width / height - 1) < 0.18 ? 0.08 : 0;
    const cleanBackgroundScore = nearWhiteRatio * 1.2 + veryWhiteRatio * 0.8 - darkRatio * 0.45 + squareLikeBonus;
    const visibleProductScore = coloredRatio > 0.03 && coloredRatio < 0.55 ? 0.25 : 0;
    return Number((cleanBackgroundScore + visibleProductScore).toFixed(4));
  } catch (_) {
    return 0;
  }
}

const scoredPaths = [];
for (let i = 0; i < orderedPaths.length; i++) {
  const p = orderedPaths[i];
  scoredPaths.push({ path: p, originalIndex: i, identityScore: await scoreProductIdentityReference(p) });
}
const identityReferences = scoredPaths
