function tpl(str, vars) {
  let out = str;
  for (const [k, v] of Object.entries(vars)) {
    out = out.split('{{' + k + '}}').join(v == null ? '' : String(v));
  }
  return out;
}

function basename(p) {
  try { return path.basename(String(p || '')); } catch (_) { return String(p || ''); }
