function collectProductReferenceImages(source) {
  const explicitMax = Number(source.max_product_reference_images || source.product_image_count || source.image_count || 0);
  const max = Math.max(explicitMax, 0);
  const images = [];
  const seen = new Set();
  for (let index = 1; index <= max; index++) {
    const dataKey = 'image_' + index + '_base64';
    const pathKey = 'image_' + index + '_path';
    const mimeKey = 'image_' + index + '_mime';
    const dataValue = String(source[dataKey] || '').trim();
    const pathValue = String(source[pathKey] || '').trim();
    if (!dataValue) continue;
    const signature = pathValue || dataValue.slice(0, 80);
    if (seen.has(signature)) continue;
    seen.add(signature);
    images.push({
      index,
      path: pathValue,
      mimeType: source[mimeKey] || 'image/jpeg',
      data: dataValue,
    });
  }
  return images;
}

