function pickVeoPrompts(parsedValue) {
  const candidates = [parsedValue?.veo_prompts, parsedValue?.video_prompts, parsedValue?.veo_prompt_pack];
  for (const candidate of candidates) {
    if (Array.isArray(candidate)) return candidate;
  }
  return [];
}

function normalizeVeoPrompts(parsedValue, shotList) {
  const rawPrompts = pickVeoPrompts(parsedValue);
  if (rawPrompts.length !== shotList.length) {
    throw new Error('脚本转提示词编译失败：veo_prompts 数量必须等于 shots 数量 ' + shotList.length + '，实际为 ' + rawPrompts.length + '。');
  }
  const byShotId = new Map();
  const byOrder = new Map();
  rawPrompts.forEach((entry, index) => {
    const obj = entry && typeof entry === 'object' ? entry : {};
    const shotId = String(obj.shot_id || obj.id || ('shot_' + (index + 1))).trim();
    if (shotId) byShotId.set(shotId, obj);
    byOrder.set(index + 1, obj);
  });
  return shotList.map((shot, index) => {
    const shotId = String(shot.shot_id || ('shot_' + (index + 1))).trim();
    const found = byShotId.get(shotId) || byShotId.get('shot_' + (index + 1)) || byOrder.get(index + 1) || {};
    const videoPrompt = String(found.video_prompt || found.veo_prompt || found.prompt || '').trim();
    if (!videoPrompt) {
      throw new Error('脚本转提示词编译失败：' + shotId + ' 缺少 video_prompt。');
    }
    const zh = String(found.video_prompt_original_zh || found.prompt_zh || found.script_brief_zh || [
      '场景：' + (shot.scene_setting || ''),
      '动作：' + (shot.visual_action || ''),
      '产品状态：' + (shot.product_state || ''),
      '口播：' + (shot.optional_voiceover_local || ''),
      '连续性：' + (shot.continuity_requirements || ''),
    ].join(' ')).trim();
    return {
      shot_id: shotId,
      shot_order: Number(found.shot_order || found.order || index + 1),
      video_prompt: videoPrompt,
      video_prompt_original_zh: zh,
      prompt_compiler_notes: String(found.prompt_compiler_notes || found.notes || '').trim(),
      product_lock: String(found.product_lock || '').trim(),
      action_lock: String(found.action_lock || '').trim(),
      avoid: Array.isArray(found.avoid) ? found.avoid : [],
      source: 'llm_prompt_compiler',
    };
  });
}

const veoPrompts = normalizeVeoPrompts(parsed, shots);

return [
  {
    json: {
      ...(scriptRow || {}),
